from typing import List


def poly(xs: List[float], x: float) -> float:
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def find_zero(xs: List[float]) -> float:
    if len(xs) % 2 != 0:
        raise ValueError("Coefficient list must have an even number of elements.")

    if xs[-1] == 0:
        raise ValueError("Largest non-zero coefficient must be present.")

    def f(x: float) -> float:
        return poly(xs, x)

    def df(x: float) -> float:
        return sum([i * coeff * math.pow(x, i - 1) for i, coeff in enumerate(xs) if i > 0])

    x = 0.0
    for _ in range(100):  # Simple fixed number of iterations for demonstration
        fx = f(x)
        if abs(fx) < 1e-10:
            return x
        dfx = df(x)
        if dfx == 0:
            break
        x -= fx / dfx

    return x

