def is_sorted(lst):
    if len(lst) < 2:
        return True

    prev = lst[0]
    count = 1

    for num in lst[1:]:
        if num < prev:
            return False
        if num == prev:
            count += 1
            if count > 1:
                return False
        else:
            prev = num
            count = 1

    return True

def prod_signs(arr):
    if not arr:
        return None

    sign_product = 1
    magnitude_sum = 0

    for num in arr:
        if num == 0:
            return 0
        elif num < 0:
            sign_product *= -1
        magnitude_sum += abs(num)

    return magnitude_sum * sign_product

def tri(n):
    if n == 0:
        return [1]
    elif n == 1:
        return [1, 3]

    result = [1, 3, 2]
    for i in range(3, n + 1):
        if i % 2 == 0:
            result.append(1 + i / 2)
        else:
            result.append(result[i - 1] + result[i - 2] + result[i + 1])
    return result

def is_nested(string):
    stack = []
    nested = False

    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']' and stack:
            stack.pop()
            if stack:
                nested = True

    return nested and not stack

def largest_smallest_integers(lst):
    negatives = [x for x in lst if x < 0]
    positives = [x for x in lst if x > 0]

